using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[Serializable] public class EMWorldState {public string name,value;public bool boolean;}
[Serializable] public class EMWorldActor {public string className,id,owner;public List<EMWorldState> state=new List<EMWorldState>();}
[Serializable] public class EMWorldPhysics {public string shape;public bool dynamic,gravity,enabled,trigger;public float mass,radius,height;public Vector3 size,velocity;}
[Serializable] public class EMWorldObject {public string id,parent,name,mesh,material;public Vector3 position,localPosition,scale,localScale;public Quaternion rotation,localRotation;public bool hidden;public EMWorldPhysics physics;}
[Serializable] public class EMWorldUI {public string owner;public int hits,order,offHits,childHits,awakes,enables,starts,disables;public bool visible,buttonActive,interactable,canvasEnabled,buttonEnabled;public string text;}
[Serializable] public class EMWorldFrame {public string map;public List<EMWorldUI> ui=new List<EMWorldUI>();public List<EMWorldActor> actors=new List<EMWorldActor>();public List<EMWorldObject> objects=new List<EMWorldObject>();public List<EMWorldObject> templates=new List<EMWorldObject>();}
[Serializable] public class EMWorldCapture {public string status;public List<EMWorldFrame> frames=new List<EMWorldFrame>();}
public class EMWorldObserver:MonoBehaviour {
 EMWorldCapture result=new EMWorldCapture();
 void Awake(){DontDestroyOnLoad(gameObject);Time.captureDeltaTime=.02f;}
 void LateUpdate(){try{var frame=new EMWorldFrame{map=SceneManager.GetActiveScene().name};ObserveUI(frame);bool done=false;
 foreach(var b in UnityEngine.Object.FindObjectsByType<MonoBehaviour>(FindObjectsSortMode.None).Where(b=>b.GetType().Name.StartsWith("Runtime",StringComparison.Ordinal)||b.GetType().Name.StartsWith("Placement",StringComparison.Ordinal))){var row=new EMWorldActor{className=b.GetType().Name,id=b.GetInstanceID().ToString(),owner=b.gameObject.GetInstanceID().ToString()};foreach(var f in b.GetType().GetFields(BindingFlags.Instance|BindingFlags.Public)){var value=f.GetValue(b);row.state.Add(new EMWorldState{name=f.Name,boolean=f.FieldType==typeof(bool),value=f.FieldType==typeof(Canvas)||f.FieldType==typeof(UnityEngine.UI.Button)?((Component)value?((Component)value).gameObject.GetInstanceID().ToString():""):f.FieldType==typeof(GameObject)?((GameObject)value?((GameObject)value).GetInstanceID().ToString():""):f.FieldType==typeof(Transform)?((Transform)value?((Transform)value).gameObject.GetInstanceID().ToString():""):typeof(MonoBehaviour).IsAssignableFrom(f.FieldType)?((MonoBehaviour)value?((MonoBehaviour)value).GetInstanceID().ToString():""):f.FieldType==typeof(Vector3)||f.FieldType==typeof(Quaternion)?JsonUtility.ToJson(value):Convert.ToString(value,System.Globalization.CultureInfo.InvariantCulture)});}frame.actors.Add(row);if(b.GetType().Name=="RuntimeFinal"&&(int)b.GetType().GetField("Frame").GetValue(b)>=5)done=true;}
 foreach(var t in UnityEngine.Object.FindObjectsByType<Transform>(FindObjectsSortMode.None))frame.objects.Add(ObjectState(t));
 var templateIds=new HashSet<int>();foreach(var driver in UnityEngine.Object.FindObjectsByType<MonoBehaviour>(FindObjectsSortMode.None).Where(b=>b.GetType().Name.StartsWith("Runtime",StringComparison.Ordinal)))foreach(var field in driver.GetType().GetFields(BindingFlags.Instance|BindingFlags.Public).Where(f=>f.FieldType==typeof(GameObject))){var asset=(GameObject)field.GetValue(driver);if(asset&&EditorUtility.IsPersistent(asset))foreach(var t in asset.GetComponentsInChildren<Transform>(true))if(templateIds.Add(t.GetInstanceID()))frame.templates.Add(ObjectState(t));}
 result.frames.Add(frame);if(done||result.frames.Count>500){result.status=done?"CAPTURED":"TIMEOUT";File.WriteAllText(Environment.GetEnvironmentVariable("EM_WORLD_OUTPUT"),JsonUtility.ToJson(result,true));EditorApplication.Exit(done?0:1);}
 }catch(Exception ex){Debug.LogException(ex);EditorApplication.Exit(1);}}
 void ObserveUI(EMWorldFrame frame){var all=UnityEngine.Object.FindObjectsByType<MonoBehaviour>(FindObjectsInactive.Include,FindObjectsSortMode.None);var driver=all.FirstOrDefault(b=>(b.GetType().Name=="RuntimeUIDriver"||b.GetType().Name=="RuntimeUIApiDriver"));if(!driver)return;int tick=(int)driver.GetType().GetField("Frame").GetValue(driver);bool click=new[]{3,5,7,11,13,16,18}.Contains(tick);
 foreach(var counter in all.Where(b=>b.GetType().Name==(driver.GetType().Name=="RuntimeUIApiDriver"?"RuntimeUIApiCounter":"RuntimeUICounter"))){var canvas=counter.GetComponent<Canvas>();var buttonObject=(GameObject)counter.GetType().GetField("Button").GetValue(counter);var button=buttonObject.GetComponent<UnityEngine.UI.Button>();bool visible=canvas.enabled&&counter.gameObject.activeInHierarchy;if(click&&visible&&buttonObject.activeInHierarchy&&button.interactable&&button.enabled)button.onClick.Invoke();var child=buttonObject.GetComponents<MonoBehaviour>().Single(b=>b.GetType().Name==(driver.GetType().Name=="RuntimeUIApiDriver"?"RuntimeUIApiChild":"RuntimeUIChild"));frame.ui.Add(new EMWorldUI{owner=counter.gameObject.GetInstanceID().ToString(),awakes=(int)counter.GetType().GetField("Awakes").GetValue(counter),enables=(int)counter.GetType().GetField("Enables").GetValue(counter),starts=(int)counter.GetType().GetField("Starts").GetValue(counter),disables=(int)counter.GetType().GetField("Disables").GetValue(counter),hits=(int)counter.GetType().GetField("Hits").GetValue(counter),order=(int)counter.GetType().GetField("Order").GetValue(counter),offHits=(int)counter.GetType().GetField("OffHits").GetValue(counter),childHits=(int)child.GetType().GetField("Hits").GetValue(child),visible=visible,buttonActive=buttonObject.activeInHierarchy,interactable=button.interactable,canvasEnabled=canvas.enabled,buttonEnabled=button.enabled,text=buttonObject.GetComponentInChildren<UnityEngine.UI.Text>(true).text});}}
 EMWorldObject ObjectState(Transform t){var mesh=t.GetComponent<MeshFilter>();var renderer=t.GetComponent<Renderer>();return new EMWorldObject{id=t.gameObject.GetInstanceID().ToString(),parent=t.parent?t.parent.gameObject.GetInstanceID().ToString():"",name=t.name,position=t.position,localPosition=t.localPosition,rotation=t.rotation,localRotation=t.localRotation,scale=t.lossyScale,localScale=t.localScale,mesh=mesh&&mesh.sharedMesh?mesh.sharedMesh.GetInstanceID().ToString():"",material=renderer&&renderer.sharedMaterial?renderer.sharedMaterial.GetInstanceID().ToString():"",hidden=!t.gameObject.activeInHierarchy,physics=PhysicsState(t)};}
 EMWorldPhysics PhysicsState(Transform t){var c=t.GetComponent<Collider>();if(!c)return null;var b=t.GetComponent<Rigidbody>();var p=new EMWorldPhysics{shape=c is BoxCollider?"box":c is SphereCollider?"sphere":"capsule",dynamic=b&&!b.isKinematic,gravity=b&&b.useGravity,enabled=c.enabled,trigger=c.isTrigger,mass=b?b.mass:0};if(c is BoxCollider box)p.size=box.size;if(c is SphereCollider sphere)p.radius=sphere.radius;if(c is CapsuleCollider capsule){p.radius=capsule.radius;p.height=capsule.height;}if(b){var velocity=typeof(Rigidbody).GetProperty("linearVelocity")??typeof(Rigidbody).GetProperty("velocity");p.velocity=(Vector3)velocity.GetValue(b);}return p;}
}
public static class EMRuntimeWorldProbe {
 public static void Run(){EditorSceneManager.OpenScene(EditorBuildSettings.scenes.First(s=>s.enabled).path);EditorSettings.enterPlayModeOptionsEnabled=true;EditorSettings.enterPlayModeOptions=EnterPlayModeOptions.DisableDomainReload|EnterPlayModeOptions.DisableSceneReload;new GameObject("Runtime World Observer").AddComponent<EMWorldObserver>();var deadline=EditorApplication.timeSinceStartup+120;EditorApplication.update+=()=>{if(EditorApplication.timeSinceStartup>deadline)EditorApplication.Exit(2);};EditorApplication.EnterPlaymode();}
}

